  "Motif": { fr: "Motif d'intervalles de base répété par récursion.", en: "Base interval motif repeated recursively." },
  "Intervalles": { fr: "Intervalles du motif personnalisé, en demi-tons séparés par des virgules (ex. 0,3,7,10).", en: "Intervals of the custom motif, in semitones separated by commas (e.g. 0,3,7,10)." },
