  "Patron": { fr: "Motif rythmique prédéfini, ou « Personnalisé » pour utiliser le code ci-dessous.", en: "Preset rhythmic pattern, or « Custom » to use the code below." },
  "Code personnalisé": { fr: "Grille rythmique personnalisée (utilisée si le patron est « Personnalisé »).", en: "Custom rhythm grid (used when the pattern is « Custom »)." },
  "Kick": { fr: "Volume de la grosse caisse, de 0 à 100 %.", en: "Kick drum volume, from 0 to 100%." },
  "Caisse claire": { fr: "Volume de la caisse claire, de 0 à 100 %.", en: "Snare volume, from 0 to 100%." },
