// Nom anglais par identifiant de composant (fiches sans nomEn).
const NOMS_EN: Record<string, string> = {
  "analyse-audio": "Audio Analysis",
  "lecteur-analyse": "Analysis Reader",
  "classificateur-genre": "Genre Classifier",
  "amplificateur": "Amplifier",
  "reinserer-zone": "Reinsert Zone",
  "selecteur-multi-zones": "Multi-Zone Selector",
  "melangeur": "Mixer",
  "visualiseur-forme-onde": "Waveform Viewer",
};

// Nom anglais par nom de paramètre commun (params sans nomEn).
const PARAMS_EN: Record<string, string> = {
  "Périphérique": "Device", "Réduction": "Reduction", "Mode": "Mode",
  "Durée": "Duration", "Gain": "Gain", "Fondu": "Fade",
  "Clé": "Key", "Gamme": "Scale", "Tempo": "Tempo", "Volume": "Volume",
  "Mesures": "Bars", "Genre": "Genre", "Qualité": "Quality",
  "Dossier entrée": "Input folder", "Dossier sortie": "Output folder",
  "Synthèse": "Synthesis",
};

export function avecDoc(def: FicheAudio): FicheAudio {
  const n = NOTICES[def.id];
  if (n && !def.notice) { def.notice = n.fr; def.noticeEn = n.en; }
  if (!def.nomEn && NOMS_EN[def.id]) def.nomEn = NOMS_EN[def.id];
  for (const p of def.parametres ?? []) {
    if (!p.doc && !p.docEn) {
      const d = DOCS_PARAM[p.nom];
      if (d) { p.doc = d.fr; p.docEn = d.en; }
    }
    if (!p.nomEn && PARAMS_EN[p.nom]) p.nomEn = PARAMS_EN[p.nom];
  }
  return def;
}
